{
  "outcome": "escalate",
  "rationale": "We must escalate this claim because an automated fraud flag was raised for a duplicate claim matching an earlier claim. Under Section 7, claims involving potential duplication must be sent for investigation. Therefore, a senior adjuster must review the matter before any payment is issued.",
  "citations": [
    {
      "clause_id": "PREM-7.2",
      "quote": "A claim for a loss that has already been reported to us, or paid, under this policy or any other policy, must be escalated to the special investigation unit."
    }
  ]
}
